formSettings.onBeforeDataLoad:
try {
  const userName = (application.user?.name ?? "") + (application.user?.surname ? " " + application.user.surname : "");
  const personId = application.user?.personId;
  const baseDefaults = { userName: userName.trim() || (application.user?.userName ?? "there"), hasSubscription: false };
  if (!personId) { form.setFieldsValue(baseDefaults); return; }
  // Find member by Person id (Member extends Person, ids match)
  const memberFilter = JSON.stringify({ "==": [{ var: "id" }, personId] });
  let memberResp;
  try {
    memberResp = await http.get("/api/services/app/Member/GetAll", { params: { Filter: memberFilter, MaxResultCount: 1 } });
  } catch (e) { form.setFieldsValue(baseDefaults); return; }
  const member = memberResp?.data?.result?.items?.[0];
  const subId = member?.subscription?.id;
  if (!subId) { form.setFieldsValue(baseDefaults); return; }
  const subResp = await http.get("/api/services/app/Subscription/Get", { params: { id: subId } });
  const sub = subResp?.data?.result;
  const tierId = sub?.tier?.id;
  let tier = null;
  if (tierId) {
    const tierResp = await http.get("/api/services/app/Tier/Get", { params: { id: tierId } });
    tier = tierResp?.data?.result;
  }
  const isMonthly = sub?.billingPeriod === 1 || (sub?.billingPeriod && sub.billingPeriod.itemValue === 1);
  const amountVal = isMonthly ? tier?.priceMonthly : tier?.priceAnnual;
  const period = isMonthly ? "month" : "year";
  const fmtMoney = (n) => (typeof n === "number") ? "R " + n.toLocaleString("en-ZA", { minimumFractionDigits: 0, maximumFractionDigits: 0 }) : "—";
  const fmtDate = (d) => d ? moment(d).format("DD MMM YYYY") : "—";
  const statusLabel = (sub?.status && (sub.status._displayName || sub.status.itemText)) || (sub?._statusDisplayName) || "Active";
  form.setFieldsValue({
    userName: baseDefaults.userName,
    hasSubscription: true,
    tierId: tierId,
    tierName: tier?.name ?? "Membership",
    tierBlurb: tier?.blurb ?? "",
    amountText: amountVal != null ? (fmtMoney(amountVal) + " / " + period) : "—",
    renewsAt: fmtDate(sub?.renewsAt),
    startedAt: fmtDate(sub?.startedAt),
    statusLabel: statusLabel
  });
} catch (err) {
  message.error(err?.response?.data?.error?.message ?? "Failed to load dashboard data");
  form.setFieldsValue({ userName: application.user?.name ?? "there", hasSubscription: false });
}
